@startuml

class InsuranceCompany {
  + CompanyName : string
  + RegistrationNumber : string
}

class PolicyType {
  + TypeName : string
}

class Policy {
  + PolicyNumber : string
  + CoverageAmount : double
}

class Customer {
  + CustomerId : int
  + Name : string
  + ContactInfo : string
}

class Contract {
  + ContractId : int
  + SigningDate : date
  + Status : string
}

InsuranceCompany "1" -- "0..*" Policy
InsuranceCompany "1" -- "0..*" Customer
Customer "1" -- "0..*" Contract
Policy "1" -- "0..*" Contract

@enduml

